{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "Though few studies on this topic exist, the available evidence suggests a high prevalence amongst refugees in LMIC, with wide variation between and within countries.",
      "reason": "The review describes the existing evidence state (few studies, high prevalence, and wide variation)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "The limited high-quality evidence about prevalence and risk factors for hepatitis B amongst refugees in LMIC highlights the need for further characterization to inform appropriate public health responses, noting that services should adopt a human rights approach and be tailored to the circumstances of local refugee populations- not a 'one size fits all' approach.",
      "reason": "It explains why the review is needed by linking gaps in evidence to the need for further characterization for public health response planning."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "Previous literature about HBV amongst refugees has mostly reported outcomes amongst those in high-income countries. A systematic review of HBV by Rossi et al. identified an overall prevalence of 7.2% amongst refugees and migrants arriving in low-endemic regions, and a higher risk of HBV amongst refugees compared with migrants (OR 1.42, 95% CI 1.03-2.43).",
      "reason": "It discusses similar prior reviews (Rossi et al.) and positions the current review relative to them by describing what prior literature has covered."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No intervention effect or proposed mechanism of action is described in the retrieved evidence; this appears to be a prevalence-focused review rather than an intervention review."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not describe a complex intervention or delivery context that would require a logic model."
    }
  ],
  "confidence": 63
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "No systematic review to date has assessed the prevalence of hepatitis B amongst refugees and displaced populations living in LMIC, where the highest number of refugees reside. We aim to address this gap by undertaking a systematic review of the prevalence of HBV amongst refugees, asylum seekers and IDPs in LMIC.",
      "reason": "The objective is stated (to undertake a systematic review of HBV prevalence in the specified populations in LMIC), but it is not explicitly presented in question form using a relevant question-formulation framework."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_7",
      "quote": "The CoCoPop framework was used as this review aims to address a question of prevalence.",
      "reason": "This is a prevalence review rather than an intervention-effect review; therefore PICO (or variant) planned comparisons are not applicable for this criterion."
    }
  ],
  "confidence": 74
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Inclusion criteria were articles in English language with full-­ text availability reporting the prevalence of HBV amongst refugees, asylum seekers and/or IDPs currently living in LMIC. LMIC were defined according to World Bank classification. 27 We included studies that measured HBV prevalence using hepatitis B surface antigen (HBsAg) and/or hepatitis B virus DNA. Given few existing studies on this topic, inclusion criteria were broad and no limits were applied for age, setting (e.g. camp, clinic, hospital, community), sampling method or number of participants. Refugees, asylum seeker or IDP status was determined based on article terminology, or by described characteristics of the population, noting most articles did not include definitions.",
      "reason": "The eligibility criteria for study characteristics are partially specified (population: refugees/asylum seekers/IDPs; setting: LMIC; eligible HBV measures: HBsAg and/or HBV DNA; no limits for age/setting/sampling). However, eligible study designs and any follow-up requirements are not specified in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Inclusion criteria were articles in English language with full-­ text availability reporting the prevalence of HBV amongst refugees, asylum seekers and/or IDPs currently living in LMIC.",
      "reason": "Language (English) and a publication/report characteristic (full-text availability) are specified. The retrieved evidence does not specify dissemination year, and does not specify publication or report status beyond full-text availability."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not report a distinction between exclusions due to outcomes not being measured versus outcomes not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not describe groups used in each synthesis or how they were linked to comparisons in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Given few existing studies on this topic, inclusion criteria were broad and no limits were applied for age, setting (e.g. camp, clinic, hospital, community), sampling method or number of participants.",
      "reason": "A rationale is provided for broad inclusion (few existing studies leading to no limits on age/setting/sampling/participants). However, the retrieved evidence does not clearly cover rationales for other notable restrictions (e.g., any other specific eligibility restrictions)."
    }
  ],
  "confidence": 72
}

